widget.solution:
from itertools import combinations


def has_subgroup_of_order(G, op, k):
    e = next(x for x in G if all(op(x, g) == g for g in G))
    others = [g for g in G if g != e]
    for rest in combinations(others, k - 1):
        H = set(rest) | {e}
        if all(op(a, b) in H for a in H for b in H):
            return True
    return False
